function show(){
	 const config = createConfig();
  const {status, toggle} = config;
  const st = {"all":"不限","0":"连载","1":"完结"}
  java.toast("\n当前状态：\n" + st[status] + "："+status+"\n排行榜："+toggle)
}

function setStatus(val){
	 const config = createConfig();
  config.status = String(val).trim();
  source.setVariable(JSON.stringify(config));
  source.refreshExplore()
}

