//排行榜
rankList = []
const pushRank = (title, url, size) =>
  rankList.push({
    title,
    url,
    style: {layout_flexBasisPercent: size||0.29}
  });

const genders = [{"title":"男生","value":"1"},{"title":"女生","value":"2"}]
const tops = [{"title":"推荐","value":"01"},{"title":"完结榜","value":"02"},{"title":"热搜榜","value":"03"}]

const rankUrl = "/api/novel/book/v2/top/book.do?topId=$genderId$topId&page={{page-1}}&size=10&vn=1.0.1.x&m=G8&t={{Date.now}}&ch=xiaomi&pkg=com.smart.app.jiudianjiu.xin.leisureNovel";
pushRank("排行榜","",1)
genders.forEach(({title,value})=>{
  tops.forEach(top => {
    let {title:toptitle,value:topval} = top;
    let url = rankUrl.replace("$genderId", value).replace("$topId", topval)
    pushRank(title+toptitle, url)
  })
})
